from dash import html
import plotly.graph_objects as go
from app import queries as q,figures as f
from app.components.common import *

def render(s,states,dark):
    rank=q.rank(s);thai=q.thai_score(s);comp=q.components(s);context=q.thai_context();eu=q.eu_context();t=thai.iloc[0] if not thai.empty else None
    r=rank[rank.iso3=='THA'];pos=f'อันดับ {int(r.iloc[0].rank_in_group)} จาก {len(rank)} ประเทศ' if not r.empty else 'ไทยไม่อยู่ในกลุ่มที่เลือก'
    return html.Div([html.P('03 / เสรีภาพอินเทอร์เน็ต',className='eyebrow'),html.H1('ไทยอยู่ตรงไหน ในปีเดียวกัน'),html.P('คะแนนเสรีภาพเทียบกลุ่มประเทศ และจำนวนคำตัดสินที่ไทยเผยแพร่ในช่วงเดียวกัน'),filters('3',s),html.Div([kpi('K3 · คะแนนไทย',number(int(t.total_score)) if t is not None else 'ไม่มีข้อมูล','คะแนน /100','Freedom House',be(s['fy'])),kpi('K3 · สถานะไทย',t.status_th if t is not None else 'ไม่มีข้อมูล','สถานะประเมิน','Freedom House',be(s['fy'])),kpi('K3 · ปีข้อมูล',be(s['fy']),'พ.ศ.','FOTN','ปีที่การประเมินครอบคลุม'),kpi('K3 · ปีรายงาน',be(int(t.report_edition)) if t is not None else 'ไม่มีข้อมูล','พ.ศ.','FOTN','ปีที่รายงานตีพิมพ์')],className='kpi-grid'),html.P(f'{pos} · กลุ่ม {", ".join(s["groups"])}'+(' + รัสเซีย' if s['add_rus'] else '')+f' · ปีข้อมูล {be(s["fy"])} · คะแนนเสมอใช้ RANK แล้วข้ามอันดับ',className='notice'),html.Div([panel('C3.1 · เปรียบเทียบประเทศ',graph('rank3',f.ranking(rank,dark)),'ประเทศไม่ซ้ำในปีเดียว · ไทยสีแดง · เส้นประคือมัธยฐานกลุ่ม'),panel('C3.2 · คะแนนมาจากส่วนไหน',graph('components3',f.score_components(comp,s,dark)),'แตะประเทศเพื่อดูรายปี แล้วแตะปีดูองค์ประกอบ ไม่มีข้อมูลรายเดือน')],className='grid-2'),panel('C3.3 · ไทยเท่านั้น · แสดงคู่กันเพื่อเป็นบริบท ไม่ได้วัดความสัมพันธ์',graph('context3',f.thai_pair(context,dark)),'ตัวกรองประเทศไม่มีผลกับ AFNC · คำตัดสินรวมทั้งข่าวจริง ปลอม และบิดเบือน · ปี 2562 ไม่เต็ม'),panel('C3.4 · บริบท EUvsDisinfo',graph('eu3',f.theme(go.Figure(go.Bar(x=[be(x) for x in eu.year],y=eu.debunks.tolist(),marker_color=f.COLORS[0])),dark)),'ไม่ผูกกับประเทศ · ถึง 1 ส.ค. 2566 · ฝั่งสนับสนุนรัสเซีย'),panel('ข้อมูลเปรียบเทียบปีเดียวกัน',[download('3',states),table(rank,'3',s,['rank_in_group','country_th','iso3','data_year','report_edition','total_score','obstacles_to_access','limits_on_content','violations_of_user_rights','status_th'])]),summary(f'ไทยปีข้อมูล {be(s["fy"])} ได้ {int(t.total_score) if t is not None else "ไม่มีข้อมูล"} คะแนน · {pos} ในกลุ่มที่เลือก','คะแนนสูงหมายถึงเสรีมาก เป็นการประเมินโดยผู้เชี่ยวชาญ จำนวนคำตัดสิน AFNC ไม่ใช่อัตราข่าวปลอมของประชากร จึงยังตอบไม่ได้ว่าการปิดกั้นลดข่าวปลอมหรือไม่')])
